    private void updateGuidedUi(){
        bottom.setPadding(Ui.dp(this,8),Ui.dp(this,guided?17:10),Ui.dp(this,8),Ui.dp(this,6));
        guidedHeader.setVisibility(guided&&!immersiveControls?View.VISIBLE:View.GONE);top.setVisibility(guided||immersiveControls?View.GONE:View.VISIBLE);readerNav.setVisibility(guided?View.GONE:View.VISIBLE);progress.setVisibility(guided?View.GONE:View.VISIBLE);readerQuick.setVisibility(guided?View.GONE:View.VISIBLE);guidedZoom.setVisibility(guided?View.VISIBLE:View.GONE);canvas.setPadding(guided&&!immersiveControls?Ui.dp(this,6):0,0,guided&&!immersiveControls?Ui.dp(this,6):0,0);
        guidedOverviewButton.setText(I18n.t(this,overview?"Voltar ao quadro":"Se localizar"));
        guidedOverviewButton.setContentDescription(I18n.t(this,overview?"Voltar ao quadro selecionado":"Mostrar página inteira"));
        guidedOverviewButton.setEnabled(!loading);
        String label=loading?"Detectando…":guidedManual?"Quadros manuais":guidedFallback?"Modo aproximado":"Detecção automática";
        if(!loading&&!guidedManual&&guidedResult!=null&&guidedResult.method.startsWith("ai_"))label=guidedFallback?"IA local · Aproximado":"IA local";
        guideDetectionStatus.setText(I18n.t(this,label)+(guidedResult!=null&&!guidedManual&&!loading?" · "+Math.round(guidedResult.confidence*100)+"%":""));
        guideDetectionStatus.setTextColor(guidedFallback?Ui.RED_BRIGHT:0xff39c68c);
        guideFallbackStatus.setText(I18n.t(this,guidedFallback?"Modo aproximado":guidedManual?"Quadros manuais":"Detecção automática"));
        guideFallbackStatus.setTextColor(guidedFallback?Ui.TEXT:Ui.MUTED);guideFallbackStatus.setBackground(Ui.bordered(this,Ui.BG,guidedFallback?Ui.RED:Ui.BORDER,Ui.RADIUS_SMALL));
        ((TextView)guidedZoom.findViewWithTag("guided-counter")).setText((index+1)+" / "+book.count);
        if(pageView!=null)guideZoomStatus.setText(Math.round(pageView.renderScale()*100)+"%");
    }
    private void redetectPanels(){
        if(source==null||loading||!guided)return;
        cancelPageWork();loading=true;int ticket=++generation,n=index;boolean manga=mode.equals("manga");updateGuidedUi();
        pageTask=worker.submit(()->{try{
            PanelDetector.Result result=session.detection(n,bitmap(n),manga,true);BookSource.checkCancelled();
            runOnUiThread(()->{if(destroyed||ticket!=generation||pageView==null)return;guidedResult=result;loading=false;
                if(!guidedManual){panels=result.regions();guidedFallback=result.fallback;panelIndex=Math.min(panelIndex,panels.size()-1);focusPanel(true);save();}
                else Toast.makeText(this,I18n.t(this,"Detecção atualizada. Quadros manuais preservados. Aplique pelo editor."),Toast.LENGTH_LONG).show();
                updateCounter();
            });
        }catch(Exception e){runOnUiThread(()->{if(!destroyed&&ticket==generation){loading=false;updateCounter();Toast.makeText(this,I18n.t(this,"Não foi possível detectar os quadros."),Toast.LENGTH_LONG).show();}});}});
    }
