    private ColorFilter readerFilter(){ColorMatrix matrix=new ColorMatrix();if("sepia".equals(readerTheme))matrix.set(new float[]{.393f,.769f,.189f,0,0,.349f,.686f,.168f,0,0,.272f,.534f,.131f,0,0,0,0,0,1,0});else if("mono".equals(readerTheme))matrix.setSaturation(0);else if("dark".equals(readerTheme))matrix.setScale(.78f,.78f,.82f,1);else return null;return new ColorMatrixColorFilter(matrix);}
