    private void loadPage(){cancelPageWork();loading=true;overviewButton.setEnabled(false);int ticket=++generation,n=index;status.setText(I18n.t(this,"Carregando página ")+(n+1)+"…");String readMode=mode;guided=getSharedPreferences("reader",0).getBoolean("guided",false)&&!mode.equals("vertical")&&!mode.equals("webtoon")&&!mode.equals("dupla");boolean guide=guided;
        updateGuidedUi();
        updateCounter();
        pageTask=worker.submit(()->{Bitmap[] owned={null};try{Bitmap image=bitmap(n);int displayedStep=1;
            if(readMode.equals("dupla")&&image.getWidth()<image.getHeight()&&n>0&&n+1<book.count){Bitmap right=bitmap(n+1);if(right.getWidth()<right.getHeight()){int height=Math.min(image.getHeight(),right.getHeight());int leftWidth=image.getWidth()*height/image.getHeight(),rightWidth=right.getWidth()*height/right.getHeight();Bitmap pair=Bitmap.createBitmap(leftWidth+rightWidth,height,Bitmap.Config.RGB_565);Canvas c=new Canvas(pair);c.drawColor(Color.BLACK);Paint p=new Paint(Paint.FILTER_BITMAP_FLAG);c.drawBitmap(image,null,new Rect(0,0,leftWidth,height),p);c.drawBitmap(right,null,new Rect(leftWidth,0,leftWidth+rightWidth,height),p);image=pair;owned[0]=pair;displayedStep=2;}}
            java.util.List<RectF> manual=guide?customPanels(n):null;PanelDetector.Result result=guide&&manual==null?session.detection(n,image,readMode.equals("manga"),false):null;
            java.util.List<RectF> regions=guide?(manual!=null?manual:result.regions()):java.util.Collections.emptyList();boolean fallback=result!=null&&result.fallback;BookSource.checkCancelled();Bitmap output=image;int span=displayedStep;owned[0]=null;runOnUiThread(()->{if(destroyed||ticket!=generation||pageView==null){if(span==2)output.recycle();return;}step=span;float keepZoom=pageView.zoom,keepX=pageView.normalizedX(),keepY=pageView.normalizedY();pageView.setTheme(readerTheme);pageView.setImage(output);pageView.changePage(initial?savedZoom:keepZoom,initial?savedX:keepX,initial?savedY:keepY,restoring||persistZoom,restoring||persistPosition,autoFit,mode);initial=false;restoring=false;panels=regions;guidedFallback=fallback;guidedResult=result;guidedManual=manual!=null;panelIndex=guide&&book.guidedPage==n?Math.max(0,Math.min(book.guidedPanel,panels.size()-1)):0;displayedPage=n;loading=false;overviewButton.setEnabled(true);overviewButton.setText(I18n.t(this,guide?(overview?"Voltar ao quadro":"Se localizar"):"Encaixar"));if(guide)pageView.post(()->{if(!destroyed&&ticket==generation)focusPanel();});Ui.enter(pageView);updateCounter();save();session.keepNear(n);session.prefetch(n+span);});
        }catch(Exception e){if(owned[0]!=null)owned[0].recycle();runOnUiThread(()->{if(!destroyed&&ticket==generation){loading=false;overviewButton.setEnabled(false);status.setText(I18n.t(this,"Página indisponível"));Toast.makeText(this,error(e),Toast.LENGTH_LONG).show();}});}});
    }
    private void updateCounter(){
        status.setText((index+1)+" / "+book.count+" · "+Math.round((index+1)*100f/book.count)+"%");
        if(guided&&!panels.isEmpty()){
            String label=guidedManual?"Quadro manual ":guidedFallback?"Modo aproximado ":"Quadro ";
            status.append("\n"+I18n.t(this,label)+(panelIndex+1)+"/"+panels.size()+(guidedResult!=null&&!guidedManual?" · "+Math.round(guidedResult.confidence*100)+"%":""));
        }
        progress.setProgress(index);updateBookmarkButton();updateGuidedUi();
    }
    private void move(int direction){if(source==null)return;if(loading){jump(index+direction);return;}if(guided&&panelIndex+direction>=0&&panelIndex+direction<panels.size()){panelIndex+=direction;focusPanel(true);save();return;}jump(index+direction*(mode.equals("dupla")?step:1));}
